import { boilPath } from './boil.js';
import { RAY } from './geometry.js';
import { defaultRig, type BrowRig, type EyeRig, type RayRig, type SunnyRig } from './rig.js';
import { TRACED_ART } from './traced-art.js';

/**
 * Sunny drawn from the traced reference artwork.
 *
 * The shapes are the reference's own (`traced-art.ts`, generated by
 * `scripts/trace-reference.py`), so the hand-inked line weight, the detached
 * rays, the notched pupils, the brows and the cheek creases survive exactly.
 * The rig moves them: every part is drawn in its rest position and placed by a
 * transform that maps the rest pose onto the current one. At the default rig
 * every transform is the identity and the drawing *is* the reference.
 */

export interface TracedPaint {
  body: string;
  ray: string;
  ink: string;
  highlight: string;
}

const REST = defaultRig();

function n(v: number): string {
  if (!Number.isFinite(v)) return '0';
  const r = Math.round(v * 1000) / 1000;
  return Object.is(r, -0) ? '0' : String(r);
}

function safeRatio(value: number, rest: number): number {
  return rest === 0 ? 1 : value / rest;
}

/**
 * A ray in its rest position is placed by: scale about its own base along and
 * across its axis, swing about the body centre, then offset. That matches what
 * `rayPoints` does to the geometric ray, so every existing sequence moves the
 * traced rays the same way it moved the old ones.
 */
function rayTransform(ray: RayRig, index: number): string {
  const restAngle = RAY.anglesDeg[index] ?? ray.angleDeg;
  const angle = ray.angleDeg + ray.rotation;
  const rad = (restAngle * Math.PI) / 180;
  const bx = Math.sin(rad) * RAY.baseRadius;
  const by = -Math.cos(rad) * RAY.baseRadius;
  const length = Math.max(0, ray.lengthScale);
  const width = Math.max(0, ray.widthScale);
  return [
    `translate(${n(ray.offset.x)} ${n(ray.offset.y)})`,
    `rotate(${n(angle - restAngle)})`,
    `translate(${n(bx)} ${n(by)})`,
    `rotate(${n(restAngle)})`,
    `scale(${n(width)} ${n(length)})`,
    `rotate(${n(-restAngle)})`,
    `translate(${n(-bx)} ${n(-by)})`,
  ].join(' ');
}

/** Map a feature's rest placement onto its current one. */
function featureTransform(
  now: { x: number; y: number; rotation: number },
  rest: { x: number; y: number; rotation: number },
  sx: number,
  sy: number,
): string {
  return [
    `translate(${n(now.x)} ${n(now.y)})`,
    `rotate(${n(now.rotation)})`,
    `scale(${n(sx)} ${n(sy)})`,
    `rotate(${n(-rest.rotation)})`,
    `translate(${n(-rest.x)} ${n(-rest.y)})`,
  ].join(' ');
}

function eyeScale(eye: EyeRig, rest: EyeRig): { sx: number; sy: number } {
  const closed = Math.max(0, Math.min(1, eye.closed));
  return {
    sx: safeRatio(eye.scaleX * eye.width, rest.scaleX * rest.width),
    // A blink squeezes the eye to a sliver about its own centre.
    sy: safeRatio(eye.scaleY * eye.height, rest.scaleY * rest.height) * (1 - closed * 0.92),
  };
}

/** A drawn part: a transform for its group, and the drawing inside it. */
export interface PartDrawing {
  transform: string;
  inner: string;
}

const wrapPart = (p: PartDrawing): string =>
  p.inner === '' ? '' : p.transform ? `<g transform="${p.transform}">${p.inner}</g>` : p.inner;

/** One ray as a part, unless hidden (a limb has taken it over). */
export function tracedRayPart(
  rig: SunnyRig,
  index: number,
  paint: TracedPaint,
  boil?: number,
): PartDrawing {
  const ray = rig.rays[index];
  const art = TRACED_ART.rays[index];
  if (!ray || !art || !ray.visible || ray.lengthScale <= 0.01) return { transform: '', inner: '' };
  return {
    transform: rayTransform(ray, index),
    inner:
      `<path d="${boilPath(art.ink, boil)}" fill="${paint.ink}"/>` +
      `<path d="${boilPath(art.fill, boil)}" fill="${paint.ray}"/>`,
  };
}

export function tracedRay(rig: SunnyRig, index: number, paint: TracedPaint, boil?: number): string {
  return wrapPart(tracedRayPart(rig, index, paint, boil));
}

export function tracedRays(
  rig: SunnyRig,
  paint: TracedPaint,
  hidden: readonly number[] = [],
  boil?: number,
): string {
  return rig.rays
    .map((_, index) => (hidden.includes(index) ? '' : tracedRay(rig, index, paint, boil)))
    .join('');
}

export function tracedBody(paint: TracedPaint, boil?: number): string {
  return (
    `<path d="${boilPath(TRACED_ART.body.ink, boil)}" fill="${paint.ink}"/>` +
    `<path d="${boilPath(TRACED_ART.body.fill, boil)}" fill="${paint.body}"/>`
  );
}

export function tracedEyePart(
  side: 'left' | 'right',
  eye: EyeRig,
  paint: TracedPaint,
  uid: string,
  boil?: number,
): PartDrawing {
  const rest = REST.eyes[side];
  const art = TRACED_ART.eyes[side];
  const { sx, sy } = eyeScale(eye, rest);
  const clipId = `sunny-traced-eye-${uid}${side}${boil ?? ''}`;
  // Gaze slides the pupil inside the opening, in the eye's own rest frame so
  // "left" means left whatever the eye's tilt.
  const gx = eye.gaze.x * rest.width * 0.16;
  const gy = eye.gaze.y * rest.height * 0.1;
  const inner = boilPath(art.inner, boil, 0.2);
  return {
    transform: featureTransform(eye, rest, sx, sy),
    inner: [
      `<clipPath id="${clipId}"><path d="${inner}"/></clipPath>`,
      `<path d="${boilPath(art.outer, boil, 0.2)}" fill="${paint.ink}" fill-rule="evenodd"/>`,
      `<path d="${inner}" fill="${paint.highlight}"/>`,
      `<g clip-path="url(#${clipId})">`,
      `<path d="${art.pupil}" fill="${paint.ink}" fill-rule="evenodd" transform="translate(${n(gx)} ${n(gy)})"/>`,
      `</g>`,
    ].join(''),
  };
}

export function tracedEye(
  side: 'left' | 'right',
  eye: EyeRig,
  paint: TracedPaint,
  uid: string,
  boil?: number,
): string {
  return wrapPart(tracedEyePart(side, eye, paint, uid, boil));
}

export function tracedBrowPart(
  side: 'left' | 'right',
  brow: BrowRig,
  paint: TracedPaint,
  boil?: number,
): PartDrawing {
  const rest = REST.brows[side];
  const sx = brow.scale * safeRatio(brow.length, rest.length);
  const arch = safeRatio(brow.arch, rest.arch);
  const sy = brow.scale * Math.max(-2, Math.min(2.5, arch));
  return {
    transform: featureTransform(brow, rest, sx, sy),
    inner: `<path d="${boilPath(TRACED_ART.brows[side].ink, boil, 0.2)}" fill="${paint.ink}" fill-rule="evenodd"/>`,
  };
}

export function tracedBrow(
  side: 'left' | 'right',
  brow: BrowRig,
  paint: TracedPaint,
  boil?: number,
): string {
  return wrapPart(tracedBrowPart(side, brow, paint, boil));
}

export function tracedMouthPart(rig: SunnyRig, paint: TracedPaint, boil?: number): PartDrawing {
  const rest = REST.smile;
  const smile = rig.smile;
  const sx = safeRatio(smile.span, rest.span);
  // Depth scales the curve; a negative depth turns the smile into a frown.
  const sy = Math.max(-2, Math.min(2.5, safeRatio(smile.depth, rest.depth)));
  return {
    transform: featureTransform(smile, rest, sx, sy),
    inner: `<path d="${boilPath(TRACED_ART.mouth.ink, boil, 0.2)}" fill="${paint.ink}" fill-rule="evenodd"/>`,
  };
}

export function tracedMouth(rig: SunnyRig, paint: TracedPaint, boil?: number): string {
  return wrapPart(tracedMouthPart(rig, paint, boil));
}

export function tracedFace(rig: SunnyRig, paint: TracedPaint, uid: string, boil?: number): string {
  return [
    tracedEye('left', rig.eyes.left, paint, uid, boil),
    tracedEye('right', rig.eyes.right, paint, uid, boil),
    tracedBrow('left', rig.brows.left, paint, boil),
    tracedBrow('right', rig.brows.right, paint, boil),
    tracedMouth(rig, paint, boil),
  ].join('');
}

/**
 * The old filter-based boil, kept for callers that still ask for it. The
 * renderer no longer uses it: re-rasterising a turbulence filter every frame
 * was the main cause of dropped frames. See `boil.ts`.
 */
export function boilFilter(id: string, seed: number): string {
  return (
    `<filter id="${id}" x="-5%" y="-5%" width="110%" height="110%">` +
    `<feTurbulence type="fractalNoise" baseFrequency="0.09" numOctaves="2" seed="${seed}" result="noise"/>` +
    `<feDisplacementMap in="SourceGraphic" in2="noise" scale="1.1" xChannelSelector="R" yChannelSelector="G"/>` +
    `</filter>`
  );
}
